/* Art Review and the playable share an origin in the review build. Its saved
   order assigns paintings to level slots; the slot still supplies the level
   difficulty, board size, mechanics, seed and move budget. */
if(typeof window!=='undefined'){
  try{
    const ordered=JSON.parse(localStorage.getItem('bookshelf_play_order_v1')||'null');
    if(Array.isArray(ordered)&&ordered.length===ART.length&&new Set(ordered).size===ART.length){
      const byNumber=new Map(ART.map(a=>[Number(a.file.split('/').pop().split('_')[0]),a]));
      if(ordered.every(n=>byNumber.has(n)))ART.splice(0,ART.length,...ordered.map(n=>byNumber.get(n)));
    }
  }catch(e){console.warn('Art order unavailable',e)}
  const artNumber=Number(new URLSearchParams(location.search).get('art'));
  const levelNumber=Number(new URLSearchParams(location.search).get('level'));
  if(artNumber>0&&levelNumber>=1&&levelNumber<=ART.length){
    const selected=ART.find(a=>Number(a.file.split('/').pop().split('_')[0])===artNumber);
    if(selected)ART[levelNumber-1]=selected;
  }
}
/* every collection has its own room and bookcase */
const THEMES={
 'Old Masters':        {bg:'ui/home_bg.jpg',     cls:'th-walnut', sw:'#A2652F'},
 'Modern Moods':       {bg:'ui/bg_modern.jpg',   cls:'th-deco',   sw:'#1F8C86'},
 'Grand Tour':         {bg:'ui/bg_tour.jpg',     cls:'th-travel', sw:'#5B3A29'},
 'Impressionist Garden':{bg:'ui/bg_garden.jpg',  cls:'th-garden', sw:'#F3EEDD'},
 'Grand Gallery':      {bg:'ui/bg_gallery.jpg',  cls:'th-baroque',sw:'#8E1F2B'},
 'Salon de Paris':     {bg:'ui/bg_salon.jpg',    cls:'th-salon',  sw:'#F2B8C6'},
 'Far Horizons':       {bg:'ui/bg_horizons.jpg', cls:'th-bamboo', sw:'#C9A35E'}};
const SHELF_NAMES=['Classic Walnut','Art Deco Teal','Travel Leather','Garden White','Baroque Red','Salon Pink','Bamboo'];
/* TEMP preview: levels 11-17 show the 7 shelf styles in turn, 18-20 classic */
const shelfPreview=L=>L>=11&&L<=17?L-11:L>=18&&L<=20?0:-1;
const themeOf=(art,L)=>{const k=Object.keys(THEMES);if(L&&shelfPreview(L)>=0)return THEMES[k[shelfPreview(L)]];return L?THEMES[k[Math.floor((L-1)/10)%k.length]]:(THEMES[art.album]||THEMES['Old Masters'])};
const CADENCE=[2,3,4,6,3,5,7,4,8,9];
const ROLE={2:'easy',3:'easy',4:'normal',5:'normal',6:'spike',7:'hard',8:'hard',9:'peak'};

function difficultyOf(L){let d=CADENCE[(L-1)%10];
  if(L<=10)d=Math.min(d,[2,2,3,3,2,3,4,3,4,5][L-1]);   // tutorial band: gentle
  else if(L<=20)d=Math.min(d,7);                          // soften first real peak
  return d}

/* grid size grows by band and by the cadence inside the band */
function gridOf(L,d){   // [shelves, books per shelf] — the bookcase grows level by level
  if(L<=2)return[2,4];if(L<=5)return[2,5];
  if(L<=10)return d>=4?[3,5]:[2,6];
  if(L<=20)return d>=6?[3,6]:[3,5];
  if(L<=35)return d>=8?[4,6]:d>=6?[3,7]:[3,6];
  if(L<=60)return d>=8?[4,7]:d>=6?[4,6]:[3,7];
  if(L<=80)return d>=9?[5,7]:d>=7?[4,7]:[4,6];
  if(L<=100)return d>=9?[5,8]:d>=7?[5,7]:d>=5?[4,7]:[4,6];
  return d>=9?[6,9]:d>=7?[6,8]:d>=5?[5,8]:[5,7]}   // 101+: big shelves, always with the Golden Frame
/* Golden Frame: on shelves of 30+ books, a book that reaches its home on the outer edge locks in place */
const FRAME_MIN=30;
/* framed shelves waste far fewer moves (sim: tail drops from 30x to ~1.3x), so the factors are much tighter; +2 safety in game */
const MOVE_K_FRAME={2:1.26,3:1.19,4:1.23,5:1.16,6:1.14,7:1.16,8:1.15,9:1.12};

/* move limit = optimal swaps x factor. Factors were calibrated with sim/sim.js: a simulated player that makes
   a wrong move 30% of the time wins first try ~95% (d2) / 90 / 80 / 72 / 60 / 55 / 48 / 40% (d9).
   Over a 10-level cycle that is ~1.5 attempts per win (checklist target 1.4-1.7). */
const MOVE_K={2:2.3,3:1.85,4:1.7,5:1.42,6:1.28,7:1.21,8:1.19,9:1.17};
function slackOf(d){return MOVE_K[d]-1}

/* when each obstacle / special book first appears (intro level teaches only that one thing) */
const MECH=Object.assign({stars:31,hidden:41,links:51,locks:61,ticks:71,keyBook:80},(typeof window!=='undefined'&&window.BS_CFG&&window.BS_CFG.mech)||{});
function modsOf(L,d,n){const m={locks:0,lockHp:1,links:0,hidden:0,stars:0,ticks:0,tickN:7,keyBook:0};
  const add=k=>{if(k==='locks'){m.locks=1;m.lockHp=2}else if(k==='ticking'){m.ticks=1;m.tickN=8}else if(k==='ribbons')m.links=1;else if(k==='keyBook')m.keyBook=1;else m[k]=1};
  if(L<80){for(const [kind,intro] of [['stars',MECH.stars],['hidden',MECH.hidden],['ribbons',MECH.links],['locks',MECH.locks],['ticking',MECH.ticks]])
      if([intro,intro+4,intro+7].includes(L))add(kind);return m}
  if(L===80){add('locks');add('keyBook');return m}
  const off=L%10,offsets=[0,2,4,7];if(!offsets.includes(off))return m;
  if(d>=9){add(Math.floor(L/10)%2===0?'stars':'hidden');return m}
  const types=['stars','hidden','ribbons','locks','ticking'];const primary=types[(Math.floor(L/10)+offsets.indexOf(off))%types.length];add(primary);
  if(d>=7&&off===7)add(primary==='hidden'?'stars':'hidden');if(primary==='locks'&&L%40===2)add('keyBook');return m}
function levelDef(L){const baseD=difficultyOf(L),d=L===80?6:baseD,[rows,cols]=gridOf(L,baseD),n=rows*cols;
  return{L,d,role:ROLE[d]||'normal',rows,cols,n,slack:slackOf(d),mods:modsOf(L,d,n),art:ART[(L-1)%ART.length],seed:L*7919+13,
    badge:d>=9?'Super Hard':d>=7?'Hard':'',reward:d>=9?140:d>=7?100:d>=6?80:55}}

/* deterministic RNG */
function rng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}

if(typeof module!=='undefined')module.exports={MECH,THEMES,themeOf,FRAME_MIN,MOVE_K_FRAME,ART,CADENCE,difficultyOf,gridOf,slackOf,modsOf,levelDef,rng};

